{
  "description": "The creature is a four-legged, wolf-shaped animal shown in right-facing profile against a plain light background. Its head, neck, torso, hind legs and tail are covered in thick, shaggy fur in shades of gray, brown and cream like a gray wolf, while its back, shoulders and hips are covered by a dark, glossy, bluish-black bumpy carapace with raised nodules and barnacle-like bumps. Its two hind legs end in typical wolf paws with claws, while its two front legs are furry to the lower joint and then terminate in large, dark, spotted crab-like claws with pincers that rest on the ground. It has a long, bushy, fur-covered tail hanging down at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a wolf head with an elongated muzzle, black nose, slightly open mouth, yellow-brown eyes, and gray, white and tan fur",
      "where": "at the front end of the body, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two pointed, upright, triangular ears with dark interiors and light fur edges",
      "where": "on top of the head"
    },
    {
      "part": "legs",
      "looks_like": "four legs; the two hind legs are fully fur-covered wolf legs with visible joints, the two front legs are thickly furred on the upper portion and become smooth, dark, jointed crab-like limbs on the lower portion",
      "where": "two hind legs under the rear body, two front legs under the chest and shoulders, all supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "hind feet are wolf paws with toes and dark claws; front feet are large, dark bluish-black crab chelae (pincers) with spotted texture, a movable black-tipped finger and a joint where they meet the furry leg",
      "where": "at the bottom of each leg; hind paws on the ground at the rear, crab claws on the ground at the front"
    },
    {
      "part": "tail",
      "looks_like": "a long, thick, bushy tail covered in gray and dark fur, tapering slightly toward the tip",
      "where": "extending down and slightly outward from the rear of the body"
    },
    {
      "part": "shell",
      "looks_like": "a dark, glossy, hard-looking carapace with a bumpy, wet appearance and scattered raised round nodules in black, brown and gold tones",
      "where": "covering the dorsal side from the back of the neck across the shoulders, mid-back and over the hips"
    },
    {
      "part": "plates",
      "looks_like": "several overlapping, segmented, spiny-edged plates with the same dark bumpy texture as the shell, with visible seams between them",
      "where": "along the midline of the back, with one large plate over the shoulders, one over the mid-back, and smaller plates toward the rear and on the sides over the hips"
    },
    {
      "part": "markings",
      "looks_like": "thick shaggy fur with mixed gray, charcoal, cream and tan coloration, lighter on the muzzle, chest, belly and inner legs, darker on the back and tail, and a dense ruff around the neck",
      "where": "covering the head, neck, sides, belly, legs and tail, surrounding the shell plates"
    }
  ],
  "attached_objects": [],
  "animals": [
    "wolf",
    "crab"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
